@Test
  public void invalidChar() throws Exception {
    try {
      calculator.enter('A');
      throw new AssertionFailureNotDetectedError();
    }
    catch (IllegalArgumentException e) {
      assertEquals(e.getMessage(), "Character 'A' is not supported");
    }
  }

